import{_ as t,o as a,c as n,a4 as o}from"./chunks/framework.DCsBdTIw.js";const k=JSON.parse('{"title":"关于 Tokeness","description":"Tokeness 是 AI API 网关，提供 OpenAI 兼容接口，支持多模型统一调用、API Key 管理、用量追踪和额度控制。","frontmatter":{"title":"关于 Tokeness","description":"Tokeness 是 AI API 网关，提供 OpenAI 兼容接口，支持多模型统一调用、API Key 管理、用量追踪和额度控制。","head":[["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@type\\": \\"SoftwareApplication\\",\\n  \\"name\\": \\"Tokeness\\",\\n  \\"applicationCategory\\": \\"DeveloperApplication\\",\\n  \\"operatingSystem\\": \\"Any\\",\\n  \\"url\\": \\"https://tokeness.io\\",\\n  \\"description\\": \\"Tokeness is an AI API gateway providing OpenAI-compatible access to multiple AI models, with API key management, quota control, and usage logging.\\",\\n  \\"offers\\": {\\n    \\"@type\\": \\"Offer\\",\\n    \\"priceCurrency\\": \\"CNY\\",\\n    \\"description\\": \\"Pre-paid, pay-per-token pricing. See the Tokeness console for current model prices.\\"\\n  },\\n  \\"provider\\": {\\n    \\"@type\\": \\"Organization\\",\\n    \\"name\\": \\"Tokeness\\",\\n    \\"url\\": \\"https://tokeness.io\\"\\n  }\\n}\\n"]]},"headers":[],"relativePath":"zh/about.md","filePath":"zh/about.md","lastUpdated":1784332800000}'),r={name:"zh/about.md"};function s(i,e,d,l,h,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="关于-tokeness" tabindex="-1">关于 Tokeness <a class="header-anchor" href="#关于-tokeness" aria-label="Permalink to &quot;关于 Tokeness&quot;">​</a></h1><p>Tokeness 是面向开发者的 AI API 网关。你用一个 API Key 和统一的接入地址调用不同 AI 模型，并在控制台查看余额、日志和用量。</p><h2 id="产品定位" tabindex="-1">产品定位 <a class="header-anchor" href="#产品定位" aria-label="Permalink to &quot;产品定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>产品类型</td><td>AI API 网关</td></tr><tr><td>标准 Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>常用协议</td><td>OpenAI 兼容、OpenAI Responses API、Anthropic API</td></tr><tr><td>控制台</td><td><a href="https://tokeness.io" target="_blank" rel="noreferrer">tokeness.io</a></td></tr><tr><td>文档站</td><td><a href="https://docs.tokeness.io" target="_blank" rel="noreferrer">docs.tokeness.io</a></td></tr><tr><td>计费模式</td><td>先充值后调用，按实际消耗扣费</td></tr></tbody></table><h2 id="tokeness-解决什么问题" tabindex="-1">Tokeness 解决什么问题 <a class="header-anchor" href="#tokeness-解决什么问题" aria-label="Permalink to &quot;Tokeness 解决什么问题&quot;">​</a></h2><p>Tokeness 把模型接入、Key 管理、额度控制和用量追踪放在同一个控制台里。对开发者来说，接入时通常只需要配置 Base URL、API Key 和模型名；业务代码仍按 OpenAI 兼容接口调用。</p><p>常见使用场景包括：</p><ul><li>用一个 Key 接入多个模型供应商。</li><li>给开发、生产、客户项目分别创建 API Key。</li><li>在控制台查看调用日志、余额和消耗。</li><li>让支持自定义 OpenAI Base URL 的工具接入 Tokeness。</li></ul><h2 id="接入事实" tabindex="-1">接入事实 <a class="header-anchor" href="#接入事实" aria-label="Permalink to &quot;接入事实&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>官方答案</th></tr></thead><tbody><tr><td>Tokeness 的 OpenAI 兼容地址是什么？</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key 从哪里创建？</td><td>Tokeness 控制台的 API 密钥页面</td></tr><tr><td>模型名从哪里复制？</td><td>Tokeness 控制台或模型广场</td></tr><tr><td>价格以哪里为准？</td><td>控制台模型广场或正式报价</td></tr><tr><td>调用记录在哪里看？</td><td>控制台的使用日志和数据看板</td></tr></tbody></table><h2 id="支持的接入方式" tabindex="-1">支持的接入方式 <a class="header-anchor" href="#支持的接入方式" aria-label="Permalink to &quot;支持的接入方式&quot;">​</a></h2><p>Tokeness 支持所有可自定义 OpenAI Base URL 的客户端和 SDK。文档站已经提供这些接入指南：</p><ul><li><a href="/zh/integrations/openai-compatible">OpenAI 兼容接入</a></li><li><a href="/zh/integrations/openai-responses">OpenAI Responses API</a></li><li><a href="/zh/integrations/anthropic-api">Anthropic API</a></li><li><a href="/zh/integrations/custom-api-key">自定义 API 与 Key</a></li><li><a href="/zh/integrations/claude-code">Claude Code</a></li><li><a href="/zh/integrations/cursor">Cursor</a></li><li><a href="/zh/integrations/codex-cli">Codex CLI</a></li><li><a href="/zh/integrations/dify">Dify</a></li><li><a href="/zh/integrations/n8n">n8n</a></li><li><a href="/zh/integrations/open-webui">Open WebUI</a></li></ul><h2 id="计费与用量" tabindex="-1">计费与用量 <a class="header-anchor" href="#计费与用量" aria-label="Permalink to &quot;计费与用量&quot;">​</a></h2><p>Tokeness 采用先充值后调用的模式。每次 API 调用按实际消耗扣费，具体模型价格以控制台展示为准。公开文档只说明计费口径，不承诺固定价格。</p><p>成本控制建议：每个项目使用独立 Key，开发测试设置较小额度，高消耗任务先用小样本验证，并定期查看使用日志和数据看板。</p><h2 id="官方入口" tabindex="-1">官方入口 <a class="header-anchor" href="#官方入口" aria-label="Permalink to &quot;官方入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>地址</th></tr></thead><tbody><tr><td>官网与控制台</td><td><a href="https://tokeness.io" target="_blank" rel="noreferrer">https://tokeness.io</a></td></tr><tr><td>文档站</td><td><a href="https://docs.tokeness.io" target="_blank" rel="noreferrer">https://docs.tokeness.io</a></td></tr><tr><td>API Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>联系邮箱</td><td><a href="mailto:contact@tokeness.io" target="_blank" rel="noreferrer">contact@tokeness.io</a></td></tr></tbody></table>',18)])])}const A=t(r,[["render",s]]);export{k as __pageData,A as default};
